import {readFile} from 'node:fs/promises';
import {validatedQuery, savedFilterInput} from '../../../shared/src/index.js';
import {query} from '../client.js';

export const SEARCH_HELP = `crew search [QUERY words ...] --org ORG [--project PROJECT] [--limit N] [--cursor CURSOR]
crew search --query 'status:active AND assignee:@me' --org ORG
crew search --query-file FILE --org ORG [--all]
crew search suggest [QUERY ...] --org ORG [--caret N]
crew search check [QUERY ...]
Search matches token prefixes in keys, titles, labels, descriptions and comments.
Quoted text matches a contiguous phrase. NOT binds before AND, then OR; use parentheses.
Fields: status:, assignee:@me|unassigned|ID, label:, project:, priority>=0..4,
created>YYYY-MM-DD, updated<YYYY-MM-DD. Comparisons support =, !=, <, <=, >, >= for dates and priority.
Search lists include total, highlights, facets and nextCursor. --all traverses every page.
Results and suggestions obey your current project access and insight:read token scope.`;
export const FILTER_HELP = `crew filter list --org ORG [--visibility personal|team|all] [--team TEAM] [--owned true] [--limit N] [--cursor CURSOR]
crew filter show FILTER
crew filter create --org ORG --name NAME [--query QUERY|--query-file FILE] [--description TEXT]
                   [--visibility personal|team] [--team TEAM]
crew filter edit FILTER [--name NAME] [--query QUERY|--query-file FILE] [--description TEXT]
                        [--visibility personal|team] [--team TEAM|none] [--revision N]
crew filter run FILTER [--limit N] [--cursor CURSOR] [--all]
crew filter delete FILTER --yes
crew filter options --org ORG
Team filters require current membership in that same-organization team. Only creators edit/delete.
A personal filter is private; passing --visibility personal clears its team.
Use --revision from the previous response to reject an intervening edit.`;

function required(value, name, help) {
  if (value == null || value === '' || value === true) throw new Error('Missing ' + name + '\n' + help);
  return value;
}

async function queryInput(args, options) {
  if (options.query !== undefined && options['query-file']) throw new Error('Choose either --query or --query-file');
  let source;
  if (options['query-file']) source = await readFile(required(options['query-file'], 'query file', SEARCH_HELP), 'utf8');
  else source = options.query !== undefined ? required(options.query, 'query text', SEARCH_HELP) : args.join(' ');
  return validatedQuery(source).query;
}

export async function collectSearchPages(client, path, parameters, all = false) {
  const first = await client.get(path + query(parameters));
  if (!all || !first.nextCursor) return first;
  const items = [...first.items];
  const seen = new Set();
  let cursor = first.nextCursor;
  while (cursor) {
    if (seen.has(cursor)) throw new Error('Server repeated a search cursor; traversal stopped');
    seen.add(cursor);
    const page = await client.get(path + query({...parameters, cursor}));
    items.push(...page.items);
    cursor = page.nextCursor;
  }
  return {...first, items, nextCursor: null};
}

export async function searchCommand({args, options, client, print}) {
  if (args[0] === 'help') {print(SEARCH_HELP); return;}
  if (args[0] === 'check') {
    const source = await queryInput(args.slice(1), options);
    print({query: source, ast: validatedQuery(source).ast, valid: true});
    return;
  }
  const orgId = required(options.org, '--org organization id', SEARCH_HELP);
  if (args[0] === 'suggest') {
    const source = options.query ?? args.slice(1).join(' ');
    print(await client.get('/search/suggestions' + query({orgId, projectId: options.project, q: source, caret: options.caret})));
    return;
  }
  const source = await queryInput(args, options);
  print(await collectSearchPages(client, '/search', {orgId, projectId: options.project, q: source, limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
}
searchCommand.help = SEARCH_HELP;

async function filterBody(options, {partial = false} = {}) {
  const body = {};
  const map = {org: 'orgId', name: 'name', description: 'description', visibility: 'visibility', team: 'teamId'};
  for (const [option, field] of Object.entries(map)) {
    if (Object.hasOwn(options, option)) body[field] = options[option];
  }
  if (body.teamId === 'none' || body.visibility === 'personal') body.teamId = null;
  if (options.query !== undefined || options['query-file']) body.query = await queryInput([], options);
  return savedFilterInput(body, {partial});
}

export async function filterCommand({args, options, client, print}) {
  const [action = 'list', id] = args;
  if (action === 'help') {print(FILTER_HELP); return;}
  if (action === 'list' || action === 'options') {
    const orgId = required(options.org, '--org organization id', FILTER_HELP);
    print(await client.get('/filters' + (action === 'options' ? '/options' : '') + query({orgId, visibility: options.visibility, teamId: options.team, owned: options.owned ? 'true' : undefined, limit: options.limit, cursor: options.cursor})));
    return;
  }
  if (action === 'create') {
    print(await client.post('/filters', await filterBody(options)));
    return;
  }
  required(id, 'saved filter id', FILTER_HELP);
  const path = '/filters/' + encodeURIComponent(id);
  if (action === 'show') {print(await client.get(path)); return;}
  if (action === 'run') {
    print(await collectSearchPages(client, path + '/search', {limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
    return;
  }
  if (action === 'edit') {
    const body = await filterBody(options, {partial: true});
    if (!Object.keys(body).length) throw new Error('Supply at least one field to edit\n' + FILTER_HELP);
    if (options.revision !== undefined) body.expectedRevision = options.revision;
    print(await client.patch(path, body));
    return;
  }
  if (action === 'delete') {
    if (!options.yes) throw new Error('Use --yes to delete a saved filter');
    print(await client.delete(path));
    return;
  }
  throw new Error('Unknown filter action: ' + action + '\n' + FILTER_HELP);
}
filterCommand.help = FILTER_HELP;

export const insightSearchCommands = {search: searchCommand, filter: filterCommand};

import {validatedQuery, quoteQueryValue} from '../../../../shared/src/index.js';

export function searchLocation(orgId, query, projectId = '') {
  const params = new URLSearchParams({orgId, q: query});
  if (projectId) params.set('projectId', projectId);
  return '/search?' + params;
}

export function searchRequest({orgId, query = '', projectId = '', cursor = '', limit = 25}) {
  if (!orgId) throw new Error('Choose an organization before searching');
  const parsed = validatedQuery(query);
  const params = new URLSearchParams({orgId, q: parsed.query, limit: String(limit)});
  if (projectId) params.set('projectId', projectId);
  if (cursor) params.set('cursor', cursor);
  return '/search?' + params;
}

export function appendQueryFilter(query, field, value) {
  const filter = field + ':' + quoteQueryValue(value);
  const base = query.trim();
  return base ? '(' + base + ') AND ' + filter : filter;
}

export function filterDraft(filter = {}, orgId = '') {
  return {orgId: filter.orgId ?? orgId, name: filter.name ?? '', query: filter.query ?? '',
    description: filter.description ?? '', visibility: filter.visibility ?? 'personal', teamId: filter.teamId ?? ''};
}

export function filterPayload(draft, revision) {
  const payload = {...draft, teamId: draft.visibility === 'team' ? draft.teamId || null : null};
  if (revision != null) payload.expectedRevision = revision;
  return payload;
}

export function nextSearchPage(history, cursor) {
  return [...history, cursor ?? ''];
}

export function previousSearchPage(history) {
  return history.length > 1 ? history.slice(0, -1) : [''];
}

export function errorPosition(error) {
  if (!Number.isInteger(error?.details?.offset)) return null;
  return {offset: error.details.offset, end: error.details.end,
    description: 'Line ' + error.details.line + ', column ' + error.details.column};
}

export function searchSnapshot(orgId, query = '', projectId = '') {
  return {orgId, query, projectId};
}

export function sameSearch(left, right) {
  return Boolean(left && right && left.orgId === right.orgId && left.query === right.query && left.projectId === right.projectId);
}

export function pagingRequest(applied, cursor, limit = 25) {
  if (!applied) throw new Error('Run a search before paging its results');
  return searchRequest({...applied, cursor, limit});
}

import {useEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {QueryEditor} from './query-editor.jsx';
import {useLiveUpdates} from '../../live.js';
import {searchRequest, searchLocation, appendQueryFilter, nextSearchPage, previousSearchPage, searchSnapshot, sameSearch} from './search-state.js';

export function Highlight({segments = []}) {
  return <>{segments.map((part, index) => part.match ? <mark key={index}>{part.text}</mark> : <span key={index}>{part.text}</span>)}</>;
}

export function SearchHelp() {
  return <details><summary>Query language and examples</summary>
    <p>Use words for token prefixes, or quotes for an exact phrase. Adjacent terms mean AND. NOT binds before AND, then OR. Parentheses override precedence.</p>
    <ul>
      <li><code>status:active AND assignee:@me</code> · my active issues</li>
      <li><code>project:APP AND (label:bug OR priority&gt;=3)</code> · urgent work</li>
      <li><code>created&gt;2026-01-01 AND updated&lt;2027-01-01</code> · UTC date window</li>
      <li><code>"search index" AND NOT status:done</code> · exact phrase excluding completed work</li>
    </ul>
    <p>Filter values match exact IDs or names; quote names with spaces. Priority ranges from 0 to 4. Dates use YYYY-MM-DD; quote full UTC ISO timestamps.</p>
  </details>;
}

export function SearchPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [input, setInput] = useState(query.q ?? '');
  const [projectId, setProjectId] = useState(query.projectId ?? '');
  const [results, setResults] = useState(null);
  const [applied, setApplied] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [stale, setStale] = useState(false);
  const [history, setHistory] = useState(['']);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState('');
  const inputRef = useRef(null);
  const requestVersion = useRef(0);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: [], projects: []}, [orgId]);
  useEffect(() => {
    if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);
  }, [organizations.data]);
  useEffect(() => {
    setOrgId(query.orgId ?? '');
    setInput(query.q ?? '');
    setProjectId(query.projectId ?? '');
    setResults(null);
    setHistory(['']);
    requestVersion.current++;
    setApplied(null);
    if (query.orgId && query.q !== undefined) run(null, [''], searchSnapshot(query.orgId, query.q, query.projectId ?? ''));
  }, [query.orgId, query.q, query.projectId]);
  useEffect(() => () => {requestVersion.current++;}, []);
  const live = useLiveUpdates({orgId, projectId, enabled: Boolean(orgId), onActivity: () => setStale(true)});
  async function run(event, nextHistory = [''], submitted = searchSnapshot(orgId, input, projectId)) {
    event?.preventDefault();
    const version = ++requestVersion.current;
    setBusy(true);
    setError(null);
    setSaved('');
    try {
      const path = searchRequest({...submitted, cursor: nextHistory.at(-1)});
      const data = await api.get(path);
      if (version !== requestVersion.current) return;
      setResults(data);
      setApplied(submitted);
      setHistory(nextHistory);
      setStale(false);
    } catch (failure) {if (version === requestVersion.current) {setError(failure); setResults(null);}}
    finally {if (version === requestVersion.current) setBusy(false);}
  }
  function clearResults() {
    requestVersion.current++;
    setResults(null);
    setApplied(null);
    setHistory(['']);
    setBusy(false);
    setError(null);
  }
  const draftChanged = applied && !sameSearch(applied, searchSnapshot(orgId, input, projectId));
  return <Page title="Search issues" actions={<a href={routeLink('/filters', {orgId})}>Saved filters</a>}>
    <Notice error={organizations.error ?? options.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Create or join an organization to search its work.</Empty> : <>
      <form onSubmit={run}>
        <div className="search-controls">
          <Field label="Organization"><select value={orgId} onChange={event => {setOrgId(event.currentTarget.value); setProjectId(''); clearResults();}}>
            <option value="">Choose an organization</option>
            {organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
          </select></Field>
          <Field label="Project"><select value={projectId} onChange={event => {setProjectId(event.currentTarget.value); clearResults();}}>
            <option value="">All accessible projects</option>
            {(options.data?.projects ?? []).map(project => <option key={project.id} value={project.id}>{project.key} · {project.name}</option>)}
          </select></Field>
        </div>
        <QueryEditor api={api} orgId={orgId} projectId={projectId} value={input} onChange={setInput} inputRef={inputRef} error={error}/>
        <div className="actions"><Button busy={busy} disabled={!orgId} type="submit">Search</Button>
          <Button type="button" disabled={!orgId || busy} onClick={() => setSaving(true)}>Save search</Button>
          <Button type="button" onClick={() => {setInput(''); clearResults();}}>Clear</Button></div>
      </form>
      <Notice error={error}/><Notice>{saved}</Notice>
      <SearchHelp/>
      <div className="actions"><span>Live updates: {live.status}</span><Button type="button" onClick={() => live.setPaused(!live.paused)}>{live.paused ? 'Resume updates' : 'Pause updates'}</Button>
        {stale && results && <Button type="button" busy={busy} onClick={event => run(event, [''], applied)}>Activity changed · refresh search</Button>}
      </div>
      {saving && <FilterForm key={orgId + input} api={api} orgId={orgId} filter={{query: input}} teams={options.data?.teams}
        onCancel={() => setSaving(false)} onSaved={filter => {setSaving(false); setSaved('Saved “' + filter.name + '”.');}}/>}
      {busy && <Loading/>}
      {results && <section aria-label="Search results">
        {draftChanged && <Notice>The query editor has unsent changes. These results and pages still use the last submitted query.</Notice>}
        <p>Results for <code>{applied?.query || 'all accessible issues'}</code></p>
        <h2>{results.total} {results.total === 1 ? 'issue' : 'issues'} found</h2>
        <div className="search-facets">{Object.entries(results.facets ?? {}).map(([field, values]) => <details key={field}>
          <summary>{field}</summary>{values.map(item => <Button key={String(item.value)} onClick={() => {setInput(appendQueryFilter(applied?.query ?? '', field, item.value)); setResults(null);}}>{String(item.value)} ({item.count})</Button>)}
        </details>)}</div>
        {!results.items.length ? <Empty>No accessible issues match this query. Try fewer filters or a shorter token prefix.</Empty> : <ol className="search-results">{results.items.map(issue => <li key={issue.id} data-testid={'search-result-' + issue.id}>
          <article><h3><a href={routeLink('/issues/' + issue.id)}>{issue.key} · <Highlight segments={issue.highlights.title}/></a></h3>
            <p><Highlight segments={issue.highlights.description}/></p>
            {issue.matchFields.includes('comments') && <p className="search-comment">Discussion: <Highlight segments={issue.highlights.comments}/></p>}
            <p>{issue.statusName} · priority {issue.priority} · {issue.assignee?.name ?? 'Unassigned'} · updated {new Date(issue.updatedAt).toLocaleString()}</p>
            <p>{issue.labels.map(label => <span className="label" key={label.id}>{label.name}</span>)}</p>
          </article>
        </li>)}</ol>}
        <div className="actions"><Button disabled={busy || history.length < 2} onClick={event => run(event, previousSearchPage(history), applied)}>Previous</Button>
          <span>Page {history.length}</span><Button disabled={busy || !results.nextCursor} onClick={event => run(event, nextSearchPage(history, results.nextCursor), applied)}>Next</Button></div>
        <a href={'#' + searchLocation(orgId, input, projectId)}>Link to this query</a>
      </section>}
    </>}
  </Page>;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {searchLocation, searchRequest, appendQueryFilter, filterDraft, filterPayload, nextSearchPage, previousSearchPage, errorPosition, searchSnapshot, sameSearch, pagingRequest} from '../src/pages/insight/search-state.js';

test('search URL and API request preserve compound query safely', () => {
  const source = 'status:active AND label:"a & b"';
  assert.equal(new URLSearchParams(searchLocation('o', source).split('?')[1]).get('q'), source);
  const path = searchRequest({orgId: 'o', query: source, cursor: 'opaque', projectId: 'p'});
  assert.equal(new URLSearchParams(path.split('?')[1]).get('cursor'), 'opaque');
});
test('search actions validate organization and query before requesting', () => {
  assert.throws(() => searchRequest({query: 'hello'}), /organization/);
  assert.throws(() => searchRequest({orgId: 'o', query: 'label:'}), error => error.details.offset === 6);
});
test('facet composition preserves OR precedence and quotes names', () => {
  assert.equal(appendQueryFilter('one OR two', 'status', 'In Progress'), '(one OR two) AND status:"In Progress"');
});
test('personal filter payload clears team and retains revision', () => {
  const draft = filterDraft({name: 'Focus', query: 'priority>=2', visibility: 'personal', teamId: 'old'}, 'o');
  const payload = filterPayload(draft, 3);
  assert.equal(payload.teamId, null); assert.equal(payload.expectedRevision, 3); assert.equal(payload.orgId, 'o');
});
test('search page navigation returns exact earlier cursors', () => {
  const history = nextSearchPage(nextSearchPage([''], 'first'), 'second');
  assert.deepEqual(previousSearchPage(history), ['', 'first']);
  assert.deepEqual(previousSearchPage(['']), ['']);
});
test('parse errors expose useful text selection coordinates', () => {
  assert.deepEqual(errorPosition({details: {offset: 4, end: 7, line: 1, column: 5}}), {offset: 4, end: 7, description: 'Line 1, column 5'});
  assert.equal(errorPosition(new Error('network')), null);
});


test('draft changes do not alter the submitted query used by cursor pages', () => {
  const applied = searchSnapshot('org', 'status:active', 'project');
  const draft = searchSnapshot('org', 'status:done', 'project');
  assert.equal(sameSearch(applied, draft), false);
  assert.equal(sameSearch(applied, {...applied}), true);
  const parameters = new URLSearchParams(pagingRequest(applied, 'opaque').split('?')[1]);
  assert.equal(parameters.get('q'), 'status:active');
  assert.equal(parameters.get('cursor'), 'opaque');
  assert.throws(() => pagingRequest(null, 'opaque'), /Run a search/);
});
